'use strict';
const MarkdownEditor=(()=>{
 const editors=new Set(),documents=new WeakSet();
 let serial=0;
 function edits(value,start,end,kind){
  if(kind==='bold'){if(value.slice(start-2,start)==='**'&&value.slice(end,end+2)==='**')return{changes:[{from:end,to:end+2,text:''},{from:start-2,to:start,text:''}],start:start-2,end:end-2};if(!value.slice(start,end))return{changes:[{from:start,to:end,text:'**重点**'}],start:start+2,end:start+4};return{changes:[{from:end,to:end,text:'**'},{from:start,to:start,text:'**'}],start:start+2,end:end+2};}
  const first=start?value.lastIndexOf('\n',start-1)+1:0,last=end>start&&value[end-1]==='\n'?end-1:end,stop=value.indexOf('\n',last),limit=stop<0?value.length:stop;
  const rows=value.slice(first,limit).split('\n'),pattern=kind==='quote'?/^> ?/:kind==='ordered'?/^\d+[.)] +/:/^[-+*] +/,remove=rows.every(row=>pattern.test(row)),changes=[];let at=first,delta=0;
  rows.forEach((row,index)=>{const match=pattern.exec(row),prefix=remove?'':kind==='quote'?'> ':kind==='ordered'?(index+1)+'. ':'- ';const count=match?.[0].length||0;changes.push({from:at,to:at+count,text:prefix});delta+=prefix.length-count;at+=row.length+1;});
  return{changes:changes.reverse(),start:first,end:limit+delta};
 }
 function mount(input,d={}){
  const document=input.ownerDocument,host=input.closest('form');if(!host)return{close(){}};
  const wrapper=document.createElement('div');wrapper.className='md-editor';input.replaceWith(wrapper);if(d.overlay)wrapper.append(d.overlay);wrapper.append(input);input.classList.add('md-input');
  const id='markdown-format-'+(++serial);if(d.labelElement){if(!d.labelElement.id)d.labelElement.id=id+'-label';input.setAttribute('aria-labelledby',d.labelElement.id);}else if(d.inputLabel)input.setAttribute('aria-label',d.inputLabel);
  const toggle=document.createElement('button');toggle.type='button';toggle.className='md-format-toggle';toggle.textContent='Aa';toggle.title='轻量 Markdown 格式';toggle.setAttribute('aria-label',d.label||'文字格式');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-controls',id);
  const label=wrapper.closest('label');if(d.toggleHost){d.toggleHost.prepend(toggle);toggle.classList.add('is-external');wrapper.classList.add('has-external-toggle');}else if(d.inline&&label?.parentElement===host){label.classList.add('md-field-label');label.insertBefore(toggle,wrapper);toggle.classList.add('is-external');wrapper.classList.add('has-external-toggle');}else wrapper.append(toggle);
  const panel=document.createElement('div');panel.className='md-format-panel';panel.hidden=true;panel.innerHTML='<div class="md-format-actions" role="toolbar" aria-label="文字格式"><button type="button" data-md="bold"><b>B</b><span>加粗</span></button><button type="button" data-md="list">• 列表</button><button type="button" data-md="ordered">1. 列表</button><button type="button" data-md="quote">❯ 引用</button><button type="button" data-md="link">↗ 链接</button></div><div class="md-link-fields" hidden><label>链接文字<input data-md-label maxlength="200"></label><label>网页地址<input data-md-url type="text" inputmode="url" placeholder="https://…"></label><button type="button" data-md-insert>插入链接</button></div><p class="md-editor-status" role="status"></p>';host.append(panel);host.classList.add('md-editor-host');
  panel.id=id;if(d.inline){panel.classList.add('is-inline');host.classList.add('has-inline-format');host.insertBefore(panel,label?.parentElement===host?label:input.closest('.discussion-compose-row'));}else host.insertBefore(panel,host.firstChild);const $=s=>panel.querySelector(s),status=$('.md-editor-status');let selection=null;
  function remember(){selection={start:input.selectionStart??input.value.length,end:input.selectionEnd??input.value.length};}
  function reveal(field){if(!panel.getBoundingClientRect)return;const bounds=panel.getBoundingClientRect(),rect=field.getBoundingClientRect();if(rect.bottom>bounds.bottom-8)panel.scrollTop+=rect.bottom-bounds.bottom+8;else if(rect.top<bounds.top+8)panel.scrollTop-=bounds.top+8-rect.top;}
  function position(){if(panel.hidden||!host.getBoundingClientRect)return;if(d.inline){if(!$('.md-link-fields').hidden)reveal($('[data-md-url]'));return;}const hostRect=host.getBoundingClientRect(),field=wrapper.getBoundingClientRect(),width=Math.min(420,hostRect.width-16);panel.style.bottom=Math.max(0,hostRect.bottom-field.top+6)+'px';panel.style.width=width+'px';panel.style.left=Math.max(8,Math.min(hostRect.width-width-8,field.right-hostRect.left-width))+'px';panel.style.right='auto';}
  function close(restoreFocus=false){if(restoreFocus&&panel.contains(document.activeElement))input.focus({preventScroll:true});panel.hidden=true;editors.delete(control);host.classList.remove('is-linking');toggle.setAttribute('aria-expanded','false');if(![...host.querySelectorAll('.md-format-panel')].some(el=>!el.hidden))host.classList.remove('is-formatting');d.onClose?.();}
  const control={close,position,contains:target=>panel.contains(target)||wrapper.contains(target)||toggle.contains(target)};
  function apply(change){if(input.disabled||input.readOnly)return;const before=input.value,changes=[...change.changes].sort((a,b)=>b.from-a.from||b.to-a.to);let value=before;for(const c of changes)value=value.slice(0,c.from)+c.text+value.slice(c.to);if(input.maxLength>0&&value.length>input.maxLength){status.textContent='内容已达到长度限制，请精简后再添加格式。';return;}
   d.onEdit?.(before,changes,value);input.value=value;input.setSelectionRange?.(change.start,change.end);close();input.dispatchEvent(new document.defaultView.Event('input',{bubbles:true}));input.focus({preventScroll:true});
  }
  toggle.onpointerdown=event=>{remember();event.preventDefault();};toggle.onclick=()=>{if(!panel.hidden){close(true);return;}if(input.disabled||input.readOnly)return;remember();for(const editor of editors)if(editor!==control)editor.close();d.onOpen?.();editors.add(control);panel.hidden=false;$('.md-link-fields').hidden=true;status.textContent='选中文字后套用，也可以直接输入 Markdown。';toggle.setAttribute('aria-expanded','true');host.classList.add('is-formatting');position();};
  panel.onpointerdown=event=>{if(event.target.closest('[data-md]'))event.preventDefault();};
  panel.onclick=event=>{const button=event.target.closest('[data-md]');if(!button)return;const range=selection||{start:input.value.length,end:input.value.length};if(button.dataset.md==='link'){if(d.canLink?.(range)===false){status.textContent='@ 队友和视频节点已可点击，请选择其他文字添加链接。';return;}$('.md-link-fields').hidden=false;host.classList.add('is-linking');$('[data-md-label]').value=input.value.slice(range.start,range.end);$('[data-md-url]').value='';status.textContent='填写网页链接，不上传文件。';position();$('[data-md-url]').focus({preventScroll:true});return;}apply(edits(input.value,range.start,range.end,button.dataset.md));};
  $('[data-md-insert]').onclick=()=>{const href=LiteMarkdown.url($('[data-md-url]').value.trim());if(!href){status.textContent='请填写有效的 http:// 或 https:// 网页地址。';return;}const range=selection||{start:input.value.length,end:input.value.length};if(d.canLink?.(range)===false){status.textContent='请选择普通文字添加链接。';return;}const label=($('[data-md-label]').value||'查看链接').replace(/[\[\]\n]/g,' '),chunk='['+label+']('+href.replace(/\(/g,'%28').replace(/\)/g,'%29')+')';apply({changes:[{from:range.start,to:range.end,text:chunk}],start:range.start+chunk.length,end:range.start+chunk.length});};
  input.addEventListener('input',close);
  for(const event of ['select','keyup','pointerup'])input.addEventListener(event,remember);
  host.addEventListener('keydown',event=>{if(event.key==='Enter'&&!panel.hidden&&event.target.closest('.md-link-fields')){event.preventDefault();$('[data-md-insert]').onclick();}if(event.key==='Escape'&&!panel.hidden){event.preventDefault();event.stopPropagation();close();input.focus({preventScroll:true});}});
  if(!documents.has(document)){documents.add(document);document.addEventListener('pointerdown',event=>{for(const editor of editors)if(!editor.contains(event.target))editor.close();});const update=()=>{for(const editor of editors)editor.position();};document.defaultView.addEventListener?.('resize',update);document.defaultView.visualViewport?.addEventListener?.('resize',update);}
  return control;
 }
 return{mount,edits};
})();
if(typeof module!=='undefined')module.exports=MarkdownEditor;
